/// 返回 `value` 落在闭区间 `[low, high]` 内时的比例位置（0.0..=1.0）。
///
/// # Examples
///
/// ```
/// assert_eq!(position(5, 0, 10), 0.5);
/// ```
fn position(value: i32, low: i32, high: i32) -> f64 {
    if high == low {
        return 0.0;
    }
    (value - low) as f64 / (high - low) as f64
}

fn main() {
    println!("position(5, 0, 10) = {}", position(5, 0, 10));
    println!("position(0, 0, 10) = {}", position(0, 0, 10));
    println!("文档内代码块会被 cargo test 当作 doctest 运行");
}

