use std::hint::black_box;
use std::time::Instant;

fn sum_of_squares(n: u64) -> u64 {
    let mut acc = 0u64;
    for i in 1..=n {
        acc += i * i;
    }
    acc
}

fn bench(label: &str, rounds: usize, mut f: impl FnMut() -> u64) {
    // 预热：让缓存与分支预测进入稳态
    for _ in 0..3 {
        black_box(f());
    }
    let mut best = u128::MAX;
    for _ in 0..rounds {
        let start = Instant::now();
        black_box(f());
        let elapsed = start.elapsed().as_nanos();
        if elapsed < best {
            best = elapsed;
        }
    }
    println!("{}: {} 轮采样完成", label, rounds);
    let _ = best;
}

fn main() {
    bench("sum_of_squares(100)", 5, || sum_of_squares(100));
    println!("verify(sum_of_squares(1000)) = {}", sum_of_squares(1000));
    println!("计时取最小值, 输入与档位固定才可比较");
}

