use std::hint::black_box;
use std::time::Instant;

fn fib_loop(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let t = a + b;
        a = b;
        b = t;
    }
    a
}

fn bench(label: &str, rounds: usize, mut f: impl FnMut() -> u64) {
    for _ in 0..3 { black_box(f()); }
    let mut best = u128::MAX;
    for _ in 0..rounds {
        let start = Instant::now();
        black_box(f());
        best = best.min(start.elapsed().as_nanos());
    }
    println!("{}: {} 轮采样完成", label, rounds);
    let _ = best;
}

fn main() {
    bench("fib_loop(30)", 5, || fib_loop(30));
    println!("fib_loop(30) = {}", fib_loop(30));
}

