fn min_max(xs: &[i32]) -> (i32, i32) {
    let mut lo = xs[0];
    let mut hi = xs[0];
    for &x in xs {
        if x < lo { lo = x; }
        if x > hi { hi = x; }
    }
    (lo, hi)
}

fn main() {
    let point = (3, 7);
    let (x, y) = point;
    println!("point = ({}, {})", x, y);

    let week = ["一", "二", "三", "四", "五", "六", "日"];
    let [first, .., last] = week;
    println!("首日 = {}, 末日 = {}, 长度 = {}", first, last, week.len());

    let (lo, hi) = min_max(&[4, 1, 9, 2, 8]);
    println!("min = {}, max = {}", lo, hi);
}

