fn swap_two(values: &mut [i32], i: usize, j: usize) {
    if i == j || i >= values.len() || j >= values.len() {
        return;
    }
    if i < j {
        let (left, right) = values.split_at_mut(j);
        std::mem::swap(&mut left[i], &mut right[0]);
    } else {
        let (left, right) = values.split_at_mut(i);
        std::mem::swap(&mut left[j], &mut right[0]);
    }
}

fn pairwise_double(values: &mut Vec<i32>) {
    // 用 zip 把相邻两个不重叠的可变引用配成对
    let mut it = values.iter_mut();
    while let (Some(a), Some(b)) = (it.next(), it.next()) {
        *a *= 2;
        *b *= 2;
    }
}

fn main() {
    let mut data = [1, 2, 3, 4, 5];
    swap_two(&mut data, 0, 4);
    println!("swapped = {:?}", data);

    let mut nums = vec![1, 2, 3, 4, 5];
    pairwise_double(&mut nums);
    println!("doubled = {:?}", nums);
}

