fn is_vowel_key(event: &Event) -> bool {
    matches!(event, Event::Key(c) if "aeiou".contains(*c))
}

fn main() {
    let events = [
        Event::Key('e'),
        Event::Click { x: 1, y: 2 },
        Event::Resize(800, 600),
        Event::Quit,
    ];

    let positional: Vec<Event> = events
        .iter()
        .copied()
        .filter(|e| is_positional(e))
        .collect();
    println!("positional = {:?}", positional);
    println!("vowel keys = {}", events.iter().filter(|e| is_vowel_key(e)).count());
    println!("has quit = {}", events.iter().any(|e| matches!(e, Event::Quit)));
}

