// 064 answer: explicit Outside / InWord / InNumber state machine
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Outside,
    InWord,
    InNumber,
}

fn kind(state: State) -> &'static str {
    match state {
        State::InWord => "word",
        State::InNumber => "number",
        State::Outside => "outside",
    }
}

fn scan(input: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut state = State::Outside;
    let mut current = String::new();

    for c in input.chars() {
        let next = if c.is_whitespace() {
            State::Outside
        } else if c.is_ascii_digit() {
            State::InNumber
        } else {
            State::InWord
        };

        // 进入 Outside，或类别发生变化：先把已积累的 token 发出
        if next == State::Outside || next != state {
            if !current.is_empty() {
                tokens.push(format!("{}:{}", kind(state), current));
                current.clear();
            }
        }

        state = next;
        if state != State::Outside {
            current.push(c);
        }
    }

    if !current.is_empty() {
        tokens.push(format!("{}:{}", kind(state), current));
    }
    tokens
}

fn main() {
    for token in scan("a1 23 bc") {
        println!("{}", token);
    }
}

