    InvalidAge { age: i32, min: i32, max: i32 },
}

impl fmt::Display for RegistrationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RegistrationError::EmptyName => write!(f, "名字不能为空"),
            RegistrationError::NameTooLong { len, max } => {
                write!(f, "名字长度 {} 超过上限 {}", len, max)
            }
            RegistrationError::InvalidAge { age, min, max } => {
                write!(f, "年龄 {} 不在 [{}, {}] 内", age, min, max)
            }
        }
    }
}

impl std::error::Error for RegistrationError {}

