struct User {
    name: String,
    age: i32,
}

fn register(name: &str, age: i32) -> Result<User, RegistrationError> {
    if name.trim().is_empty() {
        return Err(RegistrationError::EmptyName);
    }
    if name.chars().count() > 12 {
        return Err(RegistrationError::NameTooLong { len: name.chars().count(), max: 12 });
    }
    if !(0..=150).contains(&age) {
        return Err(RegistrationError::InvalidAge { age, min: 0, max: 150 });
    }
    Ok(User { name: name.to_string(), age })
}

