use std::convert::TryFrom;

#[derive(Debug, PartialEq)]
struct UserId(String);

// From<String> 是无损转换：原样保留文本（不做任何解释/截断）
impl From<String> for UserId {
    fn from(value: String) -> Self {
        UserId(value)
    }
}

// 注意：不能同时写 From<&str> 和 TryFrom<&str>——core 有 blanket impl
// `impl<T, U> TryFrom<U> for T where U: Into<T>`，两者会冲突（E0119）。
// 因此这里只提供 TryFrom<&str>：要求非空且全为 ASCII 数字，并保留原文本。
impl TryFrom<&str> for UserId {
    type Error = String;

    fn try_from(value: &str) -> Result<Self, Self::Error> {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            return Err(String::from("空 id"));
        }
        if !trimmed.chars().all(|c| c.is_ascii_digit()) {
            return Err(format!("id 必须是数字: {}", trimmed));
        }
        Ok(UserId(trimmed.to_string()))
    }
}

fn main() {
    // 无损 From<String>：任意文本都原样保留
    let a: UserId = String::from("user-中文-01").into();
    let b: UserId = String::from("keep me exactly").into();
    println!("a = {:?}", a);
    println!("b = {:?}", b);

    // TryFrom<&str>：只接受数字 id，并保留原文本
    println!("{:?}", UserId::try_from(" 12345 "));
    println!("{:?}", UserId::try_from("12a"));
    println!("{:?}", UserId::try_from(""));
}

