// 可运行部分：语义版本解析与比较
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Semver {
    major: u64,
    minor: u64,
    patch: u64,
}

impl Semver {
    fn parse(text: &str) -> Option<Semver> {
        let mut parts = text.split('.');
        let major = parts.next()?.parse().ok()?;
        let minor = parts.next()?.parse().ok()?;
        let patch = parts.next()?.parse().ok()?;
        if parts.next().is_some() {
            return None;
        }
        Some(Semver { major, minor, patch })
    }

    fn is_compatible_with(&self, required: &Semver) -> bool {
        // 约定：同为 major 且自身不低于 required
        self.major == required.major && (*self >= *required)
    }
}

impl PartialOrd for Semver {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Semver {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.major, self.minor, self.patch).cmp(&(other.major, other.minor, other.patch))
    }
}

fn main() {
    let current = Semver::parse("2.3.1").unwrap();
    let required = Semver::parse("2.1.0").unwrap();
    println!("parsed={:?}", current);
    println!("compatible={}", current.is_compatible_with(&required));
    let other_major = Semver::parse("3.0.0").unwrap();
    println!("compatible={}", current.is_compatible_with(&other_major));
}

