fn parse_line(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' => {
                if in_quotes && chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = !in_quotes;
                }
            }
            ',' if !in_quotes => {
                fields.push(std::mem::take(&mut current));
            }
            _ => current.push(c),
        }
    }
    if in_quotes {
        return Err(String::from("unterminated quoted field"));
    }
    fields.push(current);
    Ok(fields)
}

fn parse_block(text: &str) -> Result<Vec<Vec<String>>, String> {
    let mut rows = Vec::new();
    for line in text.split('\n') {
        if line.trim().is_empty() {
            continue;
        }
        rows.push(parse_line(line)?);
    }
    Ok(rows)
}

fn main() {
    let rows = parse_block("a,b\nc,d\n\ne,f").unwrap();
    println!("rows={}", rows.len());
    println!("first_last={}", rows.last().unwrap()[0]);
}

