        None => println!("child parent=<dropped>"),
    }

    let orphans = {
        let temp = Rc::new(Node {
            name: String::from("temp"),
            parent: RefCell::new(Weak::new()),
            children: RefCell::new(Vec::new()),
        });
        Rc::downgrade(&temp)
    };
    // temp 的强引用已归零，upgrade 返回 None
