use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let account_a = Arc::new(Mutex::new(100i32));
    let account_b = Arc::new(Mutex::new(50i32));

    // 统一锁顺序：总是先 a 后 b，避免交叉死锁
    let (a1, b1) = (Arc::clone(&account_a), Arc::clone(&account_b));
    let t1 = thread::spawn(move || {
        let mut first = a1.lock().unwrap();
        let mut second = b1.lock().unwrap();
        *first -= 10;
        *second += 10;
    });

    // 另一个线程同样按 a -> b 顺序
    let (a2, b2) = (Arc::clone(&account_a), Arc::clone(&account_b));
    let t2 = thread::spawn(move || {
        let mut first = a2.lock().unwrap();
        let mut second = b2.lock().unwrap();
        *first -= 20;
        *second += 20;
    });

    t1.join().unwrap();
    t2.join().unwrap();
    println!("a={}", *account_a.lock().unwrap());
    println!("b={}", *account_b.lock().unwrap());

    // try_lock：拿不到就跳过，绝不阻塞等待
    let guard = account_a.try_lock();
    match guard {
        Ok(_) => println!("try_lock=acquired"),
        Err(_) => println!("try_lock=busy"),
    }
}

