use std::sync::Mutex;

fn transfer(from: &Mutex<i32>, to: &Mutex<i32>, amount: i32) {
    // 同一把锁：直接返回，否则第二次 lock 会自锁死。
    if std::ptr::eq(from, to) {
        return;
    }
    let from_addr = from as *const Mutex<i32> as usize;
    let to_addr = to as *const Mutex<i32> as usize;
    if from_addr < to_addr {
        let mut a = from.lock().unwrap();
        let mut b = to.lock().unwrap();
        *a -= amount;
        *b += amount;
    } else {
        let mut b = to.lock().unwrap();
        let mut a = from.lock().unwrap();
        *a -= amount;
        *b += amount;
    }
}

fn main() {
    let from = Mutex::new(100);
    let to = Mutex::new(0);
    transfer(&from, &to, 30);
    println!("from={}", *from.lock().unwrap());
    println!("to={}", *to.lock().unwrap());

    // 同一把锁：必须安全返回而不是死锁
    let same = Mutex::new(10);
    transfer(&same, &same, 5);
    println!("same={}", *same.lock().unwrap());
}

