use std::sync::mpsc;
use std::thread;

fn main() {
    let documents = vec![
        "the quick brown fox".to_string(),
        "jumps over the lazy dog".to_string(),
        "the fox jumps high".to_string(),
    ];

    let (word_tx, word_rx) = mpsc::channel::<(usize, String)>();
    let mut producers = Vec::new();
    for (doc_id, text) in documents.into_iter().enumerate() {
        let sender = word_tx.clone();
        producers.push(thread::spawn(move || {
            for word in text.split_whitespace() {
                sender.send((doc_id, word.to_string())).unwrap();
            }
        }));
    }
    drop(word_tx);

    let (count_tx, count_rx) = mpsc::channel::<(usize, usize, String)>();
    let consumer = thread::spawn(move || {
        use std::collections::BTreeMap;
        let mut counts: BTreeMap<usize, usize> = BTreeMap::new();
        let mut longest: BTreeMap<usize, String> = BTreeMap::new();
        for (doc_id, word) in word_rx {
            *counts.entry(doc_id).or_insert(0) += 1;
            let entry = longest.entry(doc_id).or_insert_with(String::new);
            if word.len() > entry.len() {
                *entry = word;
            }
        }
        for (doc_id, count) in counts {
            let long = longest.remove(&doc_id).unwrap_or_default();
            count_tx.send((doc_id, count, long)).unwrap();
        }
    });

    for producer in producers {
        producer.join().unwrap();
    }
    consumer.join().unwrap();

    for (doc_id, count, longest) in count_rx {
        println!("doc {} words={} longest={}", doc_id, count, longest);
    }
}

