use std::marker::PhantomPinned;
use std::pin::Pin;

#[derive(Debug)]
struct Plain {
    value: i32,
}

// Plain 自动实现 Unpin，因此可以安全地 get_mut 并移动
fn replace_value(pinned: Pin<&mut Plain>, new_value: i32) {
    // 因为 Plain: Unpin，Pin::into_inner 是安全的
    let inner: &mut Plain = Pin::into_inner(pinned);
    inner.value = new_value;
}

// 一个显式 !Unpin 的类型：用 PhantomPinned 取消自动 Unpin
#[derive(Debug)]
struct NotUnpin {
    value: i32,
    _pin: PhantomPinned,
}

fn read_pinned(pinned: Pin<&NotUnpin>) -> i32 {
    // 只能通过共享引用读取；不能拿到 &mut 去移动
    pinned.value
}

fn main() {
    let mut plain = Plain { value: 1 };
    let pinned = Pin::new(&mut plain);
    replace_value(pinned, 99);
    println!("plain={}", plain.value);

    let boxed = Box::pin(NotUnpin { value: 7, _pin: PhantomPinned });
    println!("not_unpin={}", read_pinned(boxed.as_ref()));
    println!("done=true");
}

