use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};

/// 一个由执行器轮询的任务：自己保存剩余步数。
struct TicksTask {
    remaining: usize,
    label: &'static str,
}

impl Future for TicksTask {
    type Output = String;
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<String> {
        if self.remaining == 0 {
            Poll::Ready(format!("{} done", self.label))
        } else {
            self.remaining -= 1;
            // 还有工作要做：主动唤醒自己，让它再次入队
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

/// 就绪队列 + 唤醒计数。
struct ReadyQueue {
    queue: Mutex<VecDeque<usize>>,
    wakes: AtomicUsize,
}

/// 每个任务的 waker 记录自己对应的槽位编号，唤醒时把编号推回队列。
struct TaskWake {
    slot: usize,
    ready: Arc<ReadyQueue>,
}

impl Wake for TaskWake {
    fn wake(self: Arc<Self>) {
        self.ready.wakes.fetch_add(1, Ordering::SeqCst);
        self.ready.queue.lock().unwrap().push_back(self.slot);
    }
}

fn main() {
    let ready = Arc::new(ReadyQueue { queue: Mutex::new(VecDeque::new()), wakes: AtomicUsize::new(0) });

    // 两个任务，各自有独立 waker（slot = 0, 1）
    let mut tasks: Vec<Pin<Box<dyn Future<Output = String>>>> = vec![
        Box::pin(TicksTask { remaining: 2, label: "alpha" }),
        Box::pin(TicksTask { remaining: 1, label: "beta" }),
    ];

    let wakers: Vec<Waker> = (0..tasks.len())
        .map(|slot| {
            let handle = Arc::new(TaskWake { slot, ready: Arc::clone(&ready) });
            Waker::from(handle)
        })
        .collect();

    // 初始把两个任务都入队
    {
        let mut q = ready.queue.lock().unwrap();
        q.push_back(0);
        q.push_back(1);
    }

    let mut results = Vec::new();
    loop {
        let slot = {
            let mut q = ready.queue.lock().unwrap();
            q.pop_front()
        };
        let Some(slot) = slot else {
            break;
        };
        let mut cx = Context::from_waker(&wakers[slot]);
        match tasks[slot].as_mut().poll(&mut cx) {
            Poll::Ready(value) => results.push(value),
            Poll::Pending => {} // wake 已把它推回队列
        }
    }

    results.sort();
    for line in &results {
        println!("{line}");
    }
    println!("wakes={}", ready.wakes.load(Ordering::SeqCst));
}

