        self.polls += 1;
        if self.remaining == 0 {
            Poll::Ready(format!("{} polls={}", self.label, self.polls))
        } else {
            self.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

struct ReadyQueue {
