    fn wake(self: Arc<Self>) {
        self.ready.wakes.fetch_add(1, Ordering::SeqCst);
        self.ready.queue.lock().unwrap().push_back(self.slot);
    }
}

fn main() {
    let ready = Arc::new(ReadyQueue { queue: Mutex::new(VecDeque::new()), wakes: AtomicUsize::new(0) });
    let mut tasks: Vec<Pin<Box<dyn Future<Output = String>>>> = vec![
        Box::pin(TicksTask { remaining: 2, label: "alpha", polls: 0 }),
        Box::pin(TicksTask { remaining: 1, label: "beta", polls: 0 }),
    ];
    let wakers: Vec<Waker> = (0..tasks.len())
        .map(|slot| Waker::from(Arc::new(TaskWake { slot, ready: Arc::clone(&ready) })))
        .collect();
    {
        let mut q = ready.queue.lock().unwrap();
        q.push_back(0);
        q.push_back(1);
    }
    let mut results = Vec::new();
    loop {
        let slot = ready.queue.lock().unwrap().pop_front();
        let Some(slot) = slot else { break };
        let mut cx = Context::from_waker(&wakers[slot]);
        if let Poll::Ready(value) = tasks[slot].as_mut().poll(&mut cx) {
            results.push(value);
        }
    }
    results.sort();
    for line in &results {
        println!("{line}");
    }
    println!("wakes={}", ready.wakes.load(Ordering::SeqCst));
}

