macro_rules! my_vec {
    () => { Vec::new() };
    ($($value:expr),+ $(,)?) => {{
        let mut v = Vec::new();
        $( v.push($value); )+
        v
    }};
    ($value:expr; $count:expr) => {{
        let mut v = Vec::new();
        // 先把表达式求值一次，后续只 clone，不重复求值
        let value = $value;
        for _ in 0..$count {
            v.push(value.clone());
        }
        v
    }};
}

