/// 从裸指针指向的连续 i32 数组中读取下标 `index` 处的元素。
///
/// # Safety
/// - `ptr` 必须指向至少 `len` 个已初始化、对齐的 i32。
/// - `index` 必须小于 `len`。
/// - 所指内存在本次调用期间必须保持有效且不被可变借用别名。
unsafe fn read_at(ptr: *const i32, len: usize, index: usize) -> i32 {
    debug_assert!(index < len);
    // SAFETY: 调用者保证 index < len 且 ptr 覆盖 len 个有效元素
    *ptr.add(index)
}

fn safe_read(values: &[i32], index: usize) -> Option<i32> {
    if index >= values.len() {
        return None;
    }
    // SAFETY: 已检查 index < values.len()，且 values 在整个调用期间存活
    Some(unsafe { read_at(values.as_ptr(), values.len(), index) })
}

fn main() {
    let values = [5, 6, 7, 8];
    println!("at0={:?}", safe_read(&values, 0));
    println!("at3={:?}", safe_read(&values, 3));
    println!("at9={:?}", safe_read(&values, 9));
}

