    ready_tx: mpsc::Sender<usize>,
    ready_rx: mpsc::Receiver<usize>,
}
impl Executor {
    fn new() -> Self {
        let (ready_tx, ready_rx) = mpsc::channel();
        Self { tasks: BTreeMap::new(), ready_tx, ready_rx }
    }
    fn spawn(&mut self, id: usize, future: impl Future<Output = Outcome> + 'static) -> Result<(), String> {
        if self.tasks.contains_key(&id) { return Err("duplicate task id".into()); }
        let wake = Arc::new(TaskWake { id, ready: self.ready_tx.clone(), queued: AtomicBool::new(false) });
        self.tasks.insert(id, Task { future: Box::pin(future), wake: Arc::clone(&wake) });
        wake.schedule();
        Ok(())
    }
    fn run(&mut self) -> Result<BTreeMap<usize, Outcome>, String> {
        let mut results = BTreeMap::new();
        while !self.tasks.is_empty() {
            // Block for an actual initial-ready/wake event. Pending futures are
            // not repeatedly polled, and no sleep/busy-wait loop is involved.
            let id = self.ready_rx.recv().map_err(|_| "ready queue closed")?;
            let task = match self.tasks.get_mut(&id) { Some(task) => task, None => continue };
            task.wake.queued.store(false, Ordering::Release);
            let waker = Waker::from(Arc::clone(&task.wake));
            let mut context = Context::from_waker(&waker);
            if let Poll::Ready(result) = task.future.as_mut().poll(&mut context) {
                results.insert(id, result);
                self.tasks.remove(&id);
            }
        }
        Ok(results)
    }
