fn run() -> Result<(), String> {
    let mut executor = Executor::new();
    let pending_count = Arc::new(AtomicUsize::new(0));
    let mut producers = Vec::new();
    let specs = [(1, Some(21)), (2, Some(7)), (3, None)];
    for (id, input) in specs {
        let event = Arc::new(Event::new());
        let (started_tx, started_rx) = mpsc::sync_channel(1);
        let wait = WaitEvent { event: Arc::clone(&event), first_pending: Some(started_tx), pending_count: Arc::clone(&pending_count) };
        executor.spawn(id, async move { checked_double(wait.await?) })?;
        producers.push(thread::spawn(move || {
            // Every producer waits until its future has returned Pending and
            // registered a waker; this makes the demonstration deterministic.
            if started_rx.recv().is_ok() {
                match input { Some(value) => { event.complete(Ok(value)); }, None => { event.cancel(); } }
            }
        }));
    }
    let results = executor.run()?;
    for producer in producers { producer.join().map_err(|_| "producer panicked")?; }
    assert_eq!(pending_count.load(Ordering::Relaxed), 3);
    assert_eq!(results.get(&1), Some(&Ok(42)));
    assert_eq!(results.get(&2), Some(&Ok(14)));
    assert_eq!(results.get(&3), Some(&Err(TaskError::Cancelled)));
    for (id, result) in &results {
        match result {
            Ok(value) => println!("task{id}=ok:{value}"),
            Err(TaskError::Cancelled) => println!("task{id}=cancelled"),
            Err(TaskError::Ffi(status)) => println!("task{id}=ffi-error:{status}"),
        }
    }
    let overflow = checked_double(i32::MAX) == Err(TaskError::Ffi(-2));
    // SAFETY: null is explicitly accepted and never dereferenced by this ABI.
    let null_status = unsafe { c_double(1, std::ptr::null_mut()) };
    println!("pending={} completed={}", pending_count.load(Ordering::Relaxed), results.len());
    println!("overflow={overflow} null_status={null_status}");
    Ok(())
}

fn main() {
    if let Err(error) = run() { eprintln!("executor: {error}"); std::process::exit(1); }
}

