    fn cancellation_is_terminal_and_cannot_be_overwritten() {
        let event = Event::new();
        assert!(event.cancel());
        assert!(!event.complete(Ok(10)));
        assert_eq!(event.state.lock().unwrap().result, Some(Err(TaskError::Cancelled)));
    }
    #[test]
    fn duplicate_ids_are_rejected_and_ready_tasks_finish() {
        let mut executor = Executor::new();
        executor.spawn(1, async { Ok(8) }).unwrap();
        assert!(executor.spawn(1, async { Ok(9) }).is_err());
        assert_eq!(executor.run().unwrap().get(&1), Some(&Ok(8)));
    }
}

